// VeltOS: Windows 11's "..." button on a toast: turn the app's
// notifications off, or open the notification settings (VeltOS Settings).
PlasmaComponents3.ToolButton {
    id: veltosMoreButton
    readonly property bool canTurnOff: /^(app|service):[A-Za-z0-9._-]+$/.test(modelInterface.veltosAppId)
    icon.name: "view-more-symbolic"  // Fluent draws this one horizontal
    visible: !modelInterface.inHistory && modelInterface.closable
             && modelInterface.notificationType !== NotificationManager.Notifications.JobType
    display: PlasmaComponents3.AbstractButton.IconOnly
    text: i18nd("veltos-desktop", "More options")
    Accessible.description: __applicationName

    onClicked: veltosMoreMenu.open(0, height)

    PlasmaComponents3.ToolTip {
        text: parent.text
    }

    P5Support.DataSource {
        id: veltosShell
        engine: "executable"
        connectedSources: []
        onNewData: source => disconnectSource(source)
    }

    PlasmaExtras.Menu {
        id: veltosMoreMenu
        visualParent: veltosMoreButton

        PlasmaExtras.MenuItem {
            visible: veltosMoreButton.canTurnOff
            text: i18nd("veltos-desktop", "Turn off all notifications for %1", modelInterface.applicationName)
            icon: "notifications-disabled"
            onClicked: {
                const id = modelInterface.veltosAppId;
                const group = id.startsWith("app:") ? "Applications" : "Services";
                const name = id.substring(id.indexOf(":") + 1);
                const base = "kwriteconfig6 --notify --file plasmanotifyrc --group " + group + " --group " + name;
                veltosShell.connectSource(base + " --key ShowPopups --type bool false; "
                                          + base + " --key ShowInHistory --type bool false");
                modelInterface.closeClicked();
            }
        }
        PlasmaExtras.MenuItem {
            text: i18nd("veltos-desktop", "Go to notification settings")
            icon: "configure"
            onClicked: {
                veltosShell.connectSource("veltos-settings notifications");
                modelInterface.closeClicked();
            }
        }
    }
}

